const passport = require('passport');
const { HeaderAPIKeyStrategy } = require('passport-headerapikey');
const { ApiKey, Account } = require('../models');

passport.use('api-key', new HeaderAPIKeyStrategy(
  { header: 'X-API-KEY', prefix: '' },
  true,
  async (apiKey, done, req) => {
    const keyRecord = await ApiKey.findOne({ keyHash: hashKey(apiKey), isActive: true });
    if (!keyRecord) {
      return done(null, false);
    }

    const requestedAccountId = req.query.account_id || req.headers['x-account-id'];
    if (requestedAccountId && !keyRecord.allowedAccountIds.includes(requestedAccountId)) {
      return done(null, false, { message: 'Forbidden: API key is not authorized for requested account' });
    }

    const accountId = requestedAccountId || keyRecord.defaultAccountId;
    const account = await Account.findById(accountId);
    if (!account) {
      return done(null, false, { message: 'Account not found' });
    }

    return done(null, { keyRecord, account });
  }
));
